(()=>{const out={};for(const kind of ['webgl','webgl2']){const canvas=new OffscreenCanvas(2,2),gl=canvas.getContext(kind);out[kind]={};for(const name of ['drawingBufferColorSpace','unpackColorSpace']){const rows=[];out[kind][name]=rows;rows.push(['default',gl[name]]);for(const value of ['display-p3','srgb','invalid','SRGB','',null,undefined,{},Symbol('x')]){let error=null;try{gl[name]=value}catch(e){error=e.name}rows.push([String(value),gl[name],error,gl.getError()])}gl[name]='display-p3';canvas.width=3;rows.push(['resize',gl[name]]);rows.push(['separate',new OffscreenCanvas(1,1).getContext(kind)[name]]);const d=Object.getOwnPropertyDescriptor(Object.getPrototypeOf(gl),name);let bad;try{d.get.call({})}catch(e){bad=e.name}out[kind][name+'Descriptor']=[d.get.name,d.set.name,d.enumerable,d.configurable,bad];}}return out})()
